    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    rows = [[c for c in range(w) if grid[r][c] != bg] for r in range(h)]
    cols = [[r for r in range(h) if grid[r][c] != bg] for c in range(w)]
    # Join consecutive marks only when both endpoints face the same outer edge.
    for r in range(h):
        for c1, c2 in zip(rows[r], rows[r][1:]):
            v = grid[r][c1]
            if grid[r][c2] != v:
                continue
            top1, bottom1 = r == min(cols[c1]), r == max(cols[c1])
            top2, bottom2 = r == min(cols[c2]), r == max(cols[c2])
            if (top1 or bottom1) and (top2 or bottom2):
                for c in range(c1+1,c2):
                    out[r][c] = 2
    for c in range(w):
        for r1, r2 in zip(cols[c], cols[c][1:]):
            v = grid[r1][c]
            if grid[r2][c] != v:
                continue
            left1, right1 = c == min(rows[r1]), c == max(rows[r1])
            left2, right2 = c == min(rows[r2]), c == max(rows[r2])
            if (left1 and left2) or (right1 and right2):
                for r in range(r1+1,r2):
                    out[r][c] = 2
    return out

